import type { Metadata } from 'next';
import { getAllLaptops, getLaptopBySlug, formatPrice } from '@/lib/data';

interface Props {
  params: Promise<{ slug: string }>;
}

export async function generateStaticParams() {
  const laptops = getAllLaptops();
  const params: { slug: string }[] = [];
  for (let i = 0; i < laptops.length; i++) {
    for (let j = i + 1; j < laptops.length; j++) {
      params.push({ slug: `${laptops[i].slug}-vs-${laptops[j].slug}` });
    }
  }
  return params;
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params;
  const [slugA, slugB] = parseCompareSlugs(slug);
  const a = getLaptopBySlug(slugA);
  const b = getLaptopBySlug(slugB);
  if (!a || !b) return {};
  return {
    title: `${a.brand} ${a.model} vs ${b.brand} ${b.model} 비교 | LaptopFYI`,
    description: `${a.brand} ${a.model}과 ${b.brand} ${b.model}의 스펙, 가격, 성능을 상세 비교합니다.`,
  };
}

function parseCompareSlugs(slug: string): [string, string] {
  const vsIdx = slug.indexOf('-vs-');
  if (vsIdx === -1) return [slug, ''];
  return [slug.slice(0, vsIdx), slug.slice(vsIdx + 4)];
}

export default async function ComparePage({ params }: Props) {
  const { slug } = await params;
  const [slugA, slugB] = parseCompareSlugs(slug);
  const a = getLaptopBySlug(slugA);
  const b = getLaptopBySlug(slugB);
  if (!a || !b) notFound();

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline: `${a.brand} ${a.model} vs ${b.brand} ${b.model} 비교`,
    description: `${a.brand} ${a.model}과 ${b.brand} ${b.model}의 스펙, 가격, 성능을 상세 비교합니다.`,
  };

  const specs = [
    { label: 'CPU', aVal: a.cpu, bVal: b.cpu },
    { label: 'RAM', aVal: `${a.ram_gb}GB`, bVal: `${b.ram_gb}GB` },
    { label: '스토리지', aVal: `${a.storage_gb}GB ${a.storage_type}`, bVal: `${b.storage_gb}GB ${b.storage_type}` },
    { label: '디스플레이', aVal: `${a.display_inch}" ${a.display_type}`, bVal: `${b.display_inch}" ${b.display_type}` },
    { label: '해상도', aVal: a.display_resolution, bVal: b.display_resolution },
    { label: 'GPU', aVal: a.gpu, bVal: b.gpu },
    { label: '배터리', aVal: `${a.battery_wh}Wh`, bVal: `${b.battery_wh}Wh` },
    { label: '무게', aVal: `${a.weight_kg}kg`, bVal: `${b.weight_kg}kg` },
    { label: '운영체제', aVal: a.os, bVal: b.os },
  ];

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      <main className="max-w-5xl mx-auto px-4 py-8">
        <h1 className="text-3xl font-bold mb-2 text-center">
          {a.brand} {a.model} vs {b.brand} {b.model}
        </h1>
        <p className="text-center text-gray-500 mb-8">상세 스펙 비교</p>

        <div className="grid grid-cols-3 gap-4 mb-8">
          <div className="bg-blue-50 rounded-xl p-4 text-center">
            <h2 className="font-semibold text-lg">{a.brand}</h2>
            <p className="text-sm text-gray-600">{a.model}</p>
            <p className="text-xl font-bold text-blue-700 mt-2">{formatPrice(a.price_krw)}~</p>
            <a
              href={a.refurlab_url}
              target="_blank"
              rel="noopener noreferrer"
              className="mt-3 block bg-blue-600 text-white text-sm py-2 rounded-lg hover:bg-blue-700"
            >
              리퍼랩에서 보기
            </a>
          </div>
          <div className="flex items-center justify-center">
            <span className="text-3xl font-bold text-gray-300">VS</span>
          </div>
          <div className="bg-gray-50 rounded-xl p-4 text-center">
            <h2 className="font-semibold text-lg">{b.brand}</h2>
            <p className="text-sm text-gray-600">{b.model}</p>
            <p className="text-xl font-bold text-gray-700 mt-2">{formatPrice(b.price_krw)}~</p>
            <a
              href={b.refurlab_url}
              target="_blank"
              rel="noopener noreferrer"
              className="mt-3 block bg-gray-700 text-white text-sm py-2 rounded-lg hover:bg-gray-800"
            >
              리퍼랩에서 보기
            </a>
          </div>
        </div>

        <section className="bg-white rounded-xl shadow overflow-hidden">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-gray-50 border-b">
                <th className="text-left p-3 font-semibold text-gray-500">스펙</th>
                <th className="text-center p-3 font-semibold text-blue-700">{a.brand} {a.model}</th>
                <th className="text-center p-3 font-semibold text-gray-700">{b.brand} {b.model}</th>
              </tr>
            </thead>
            <tbody>
              {specs.map((s, i) => (
                <tr key={s.label} className={i % 2 === 0 ? 'bg-white' : 'bg-gray-50'}>
                  <td className="p-3 text-gray-500">{s.label}</td>
                  <td className="p-3 text-center font-medium">{s.aVal}</td>
                  <td className="p-3 text-center font-medium">{s.bVal}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      </main>
    </>
  );
}
