import { getAllLaptops, getAllBrands, getAllCpuSeries, getAllUseCases } from '@/lib/data';

const BASE_URL = 'https://laptopfyi.com';

export default function sitemap(): MetadataRoute.Sitemap {
  const laptops = getAllLaptops();
  const brands = getAllBrands();
  const cpuSeries = getAllCpuSeries();
  const useCases = getAllUseCases();

  const laptopUrls = laptops.map((l) => ({
    url: `${BASE_URL}/laptops/${l.slug}`,
    lastModified: new Date(),
    changeFrequency: 'monthly' as const,
    priority: 0.8,
  }));

  const compareUrls: MetadataRoute.Sitemap = [];
  for (let i = 0; i < laptops.length; i++) {
    for (let j = i + 1; j < laptops.length; j++) {
      compareUrls.push({
        url: `${BASE_URL}/compare/${laptops[i].slug}-vs-${laptops[j].slug}`,
        lastModified: new Date(),
        changeFrequency: 'monthly' as const,
        priority: 0.7,
      });
    }
  }

  const brandUrls = brands.map((b) => ({
    url: `${BASE_URL}/brand/${b}`,
    lastModified: new Date(),
    changeFrequency: 'weekly' as const,
    priority: 0.6,
  }));

  const cpuUrls = cpuSeries.map((c) => ({
    url: `${BASE_URL}/cpu/${c}`,
    lastModified: new Date(),
    changeFrequency: 'monthly' as const,
    priority: 0.6,
  }));

  const useCaseUrls = useCases.map((u) => ({
    url: `${BASE_URL}/use-case/${u}`,
    lastModified: new Date(),
    changeFrequency: 'weekly' as const,
    priority: 0.7,
  }));

  return [
    { url: BASE_URL, lastModified: new Date(), changeFrequency: 'daily', priority: 1.0 },
    ...laptopUrls,
    ...compareUrls,
    ...brandUrls,
    ...cpuUrls,
    ...useCaseUrls,
  ];
}
