import type { Metadata } from 'next';
import Link from 'next/link';
import { getAllGlossaryEntries, getGlossaryEntryBySlug } from '@/lib/data';

interface Props {
  params: Promise<{ slug: string }>;
}

export async function generateStaticParams() {
  return getAllGlossaryEntries().map((g) => ({ slug: g.slug }));
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params;
  const entry = getGlossaryEntryBySlug(slug);
  if (!entry) return {};
  return {
    title: `${entry.term} 뜻 | 노트북 용어 사전 | LaptopFYI`,
    description: entry.definition.slice(0, 160),
  };
}

export default async function GlossaryPage({ params }: Props) {
  const { slug } = await params;
  const entry = getGlossaryEntryBySlug(slug);
  if (!entry) notFound();

  const allEntries = getAllGlossaryEntries();
  const relatedEntries = entry.related
    .map((s) => allEntries.find((e) => e.slug === s))
    .filter(Boolean) as typeof allEntries;

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'DefinedTerm',
    name: entry.term,
    description: entry.definition,
    inDefinedTermSet: 'https://laptopfyi.com/glossary',
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      <main className="max-w-3xl mx-auto px-4 py-8">
        <p className="text-sm text-gray-400 mb-2">{entry.category}</p>
        <h1 className="text-3xl font-bold mb-4">{entry.term}</h1>
        <div className="bg-white rounded-xl shadow p-6 mb-8">
          <p className="text-gray-700 leading-relaxed">{entry.definition}</p>
        </div>

        {relatedEntries.length > 0 && (
          <section>
            <h2 className="text-lg font-semibold mb-3">관련 용어</h2>
            <div className="flex flex-wrap gap-2">
              {relatedEntries.map((rel) => (
                <Link
                  key={rel.slug}
                  href={`/glossary/${rel.slug}`}
                  className="bg-gray-100 text-gray-700 px-3 py-1 rounded-full text-sm hover:bg-blue-50 hover:text-blue-700"
                >
                  {rel.term}
                </Link>
              ))}
            </div>
          </section>
        )}

        <div className="mt-8">
          <Link href="/glossary" className="text-blue-500 hover:underline text-sm">
            ← 전체 용어 사전
          </Link>
        </div>
      </main>
    </>
  );
}
